CREATE TABLE public.account_access(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','pending','rejected','suspended')),reason text NOT NULL DEFAULT '' CHECK(length(reason)<=500),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.account_access TO authenticated; GRANT ALL ON public.account_access TO service_role;
ALTER TABLE public.account_access ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.account_active(uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_access a WHERE a.user_id=uid AND a.status<>'active') $$;
REVOKE ALL ON FUNCTION public.account_active(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.account_active(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY account_access_read ON public.account_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,before_state jsonb NOT NULL DEFAULT '{}',after_state jsonb NOT NULL DEFAULT '{}',outcome text NOT NULL DEFAULT 'success' CHECK(outcome IN ('success','denied','failed')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit_log TO authenticated; GRANT ALL ON public.admin_audit_log TO service_role;
ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit_read ON public.admin_audit_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.platform_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),support_email text NOT NULL DEFAULT '' CHECK(length(support_email)<=255),announcement_en text NOT NULL DEFAULT '' CHECK(length(announcement_en)<=500),announcement_ar text NOT NULL DEFAULT '' CHECK(length(announcement_ar)<=500),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.platform_settings TO authenticated; GRANT ALL ON public.platform_settings TO service_role;
ALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY platform_settings_admin_read ON public.platform_settings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.recycling_partners ADD COLUMN operating_areas text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.green_vouchers ADD COLUMN admin_review text NOT NULL DEFAULT 'pending' CHECK(admin_review IN ('pending','approved','rejected'));
CREATE FUNCTION public.admin_audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prev jsonb:='{}'; curr jsonb:='{}'; eid text; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RETURN coalesce(NEW,OLD); END IF;
IF TG_OP<>'INSERT' THEN SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO prev FROM jsonb_each(to_jsonb(OLD)) WHERE key IN ('status','verification_status','approved','public_ranking','role','lifecycle','verified_kg','confirmed_recycled','partner_id','points_per_kg','rewards','winner_percents','max_discount','minimum_order','expiry_days','percent','admin_review','operating_areas','amount','source_key','announcement_en','announcement_ar','support_email'); END IF;
IF TG_OP<>'DELETE' THEN SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO curr FROM jsonb_each(to_jsonb(NEW)) WHERE key IN ('status','verification_status','approved','public_ranking','role','lifecycle','verified_kg','confirmed_recycled','partner_id','points_per_kg','rewards','winner_percents','max_discount','minimum_order','expiry_days','percent','admin_review','operating_areas','amount','source_key','announcement_en','announcement_ar','support_email'); END IF;
IF prev IS DISTINCT FROM curr OR TG_OP<>'UPDATE' THEN eid:=coalesce(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id',to_jsonb(NEW)->>'user_id',to_jsonb(OLD)->>'user_id',to_jsonb(NEW)->>'period','settings'); INSERT INTO public.admin_audit_log(actor_id,action,entity_type,entity_id,before_state,after_state) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,eid,prev,curr); END IF; RETURN coalesce(NEW,OLD); END $$;
REVOKE ALL ON FUNCTION public.admin_audit_change() FROM PUBLIC;
DO $rules$ DECLARE t text; fn text; definition text; BEGIN
FOR t IN SELECT unnest(ARRAY['profiles','user_roles','business_profiles','supplier_profiles','products','product_images','product_documents','product_sustainability_attributes','shopping_carts','cart_items','saved_products','orders','order_items','group_buying_campaigns','group_buying_participants','supplier_verification_documents','supplier_verification_history','buyer_tool_sessions','ai_recommendation_history','environmental_impact_records','recycling_businesses','recycling_partners','recycling_requests','recycling_files','recycling_settings','green_points_ledger','green_vouchers','green_supplier_consent','recycling_months','platform_settings','admin_audit_log']) LOOP EXECUTE format('CREATE POLICY account_active_required ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_active(auth.uid())) WITH CHECK(public.account_active(auth.uid()))',t); END LOOP;
FOR t IN SELECT unnest(ARRAY['account_access','user_roles','supplier_profiles','products','orders','group_buying_campaigns','recycling_businesses','recycling_partners','recycling_requests','recycling_settings','green_vouchers','green_points_ledger','recycling_months','platform_settings']) LOOP EXECUTE format('CREATE TRIGGER admin_audit_changes AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.admin_audit_change()',t); END LOOP;
FOR fn IN SELECT unnest(ARRAY['request_cart_order(uuid,jsonb)','change_order_status(uuid,text)','create_group_campaign(jsonb)','manage_group_campaign(uuid,text)','join_group_campaign(uuid,integer,jsonb)','recycling_action(text,jsonb)','admin_set_role(uuid,public.app_role)','admin_verify_supplier(uuid,text)']) LOOP SELECT pg_get_functiondef(to_regprocedure('public.'||fn)) INTO definition; IF definition IS NULL THEN RAISE EXCEPTION 'Missing function %',fn; END IF; definition:=regexp_replace(definition,'BEGIN','BEGIN IF NOT public.account_active(auth.uid()) THEN RAISE EXCEPTION ''Account inactive''; END IF;','i'); EXECUTE definition; END LOOP;
SELECT pg_get_functiondef('public.public_product(uuid)'::regprocedure) INTO definition; definition:=replace(definition,'s.verification_status = ''approved''::text','s.verification_status = ''approved''::text AND public.account_active(s.user_id)'); definition:=replace(definition,'s.verification_status=''approved''','s.verification_status=''approved'' AND public.account_active(s.user_id)'); EXECUTE definition;
END $rules$;
CREATE POLICY active_storage_required ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_active(auth.uid())) WITH CHECK(public.account_active(auth.uid()));
CREATE FUNCTION public.admin_manage(action text,payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); target uuid; prev jsonb; result jsonb; sid uuid; status_value text; BEGIN
IF NOT public.has_role(uid,'admin') THEN RAISE EXCEPTION 'Administrator required'; END IF;
BEGIN
IF action='account' THEN target:=(payload->>'userId')::uuid; status_value:=payload->>'status'; IF target=uid OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target AND role='admin') THEN RAISE EXCEPTION 'Administrators cannot be self-managed or suspended'; END IF; IF status_value NOT IN ('active','pending','rejected','suspended') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target) THEN RAISE EXCEPTION 'Invalid account'; END IF;
INSERT INTO public.account_access(user_id,status,reason,updated_by) VALUES(target,status_value,coalesce(payload->>'reason',''),uid) ON CONFLICT(user_id) DO UPDATE SET status=EXCLUDED.status,reason=EXCLUDED.reason,updated_at=now(),updated_by=uid;
ELSIF action='partner_areas' THEN target:=(payload->>'id')::uuid; IF jsonb_typeof(payload->'areas') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'areas')>30 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(payload->'areas') x WHERE length(trim(x)) NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION 'Invalid operating areas'; END IF; UPDATE public.recycling_partners SET operating_areas=ARRAY(SELECT jsonb_array_elements_text(payload->'areas')) WHERE id=target; IF NOT FOUND THEN RAISE EXCEPTION 'Partner not found'; END IF;
ELSIF action='product' THEN target:=(payload->>'id')::uuid; SELECT supplier_id INTO sid FROM public.products WHERE id=target; IF EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=sid AND user_id=uid) OR payload->>'status' NOT IN ('published','rejected','pending') THEN RAISE EXCEPTION 'Independent product review required'; END IF; UPDATE public.products SET status=payload->>'status' WHERE id=target; IF NOT FOUND THEN RAISE EXCEPTION 'Product not found'; END IF;
ELSIF action='voucher_review' THEN target:=(payload->>'id')::uuid; IF payload->>'status' NOT IN ('approved','rejected') OR EXISTS(SELECT 1 FROM public.green_vouchers WHERE id=target AND user_id=uid) THEN RAISE EXCEPTION 'Independent voucher review required'; END IF; UPDATE public.green_vouchers SET admin_review=payload->>'status' WHERE id=target AND used_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Unused voucher required'; END IF;
ELSIF action='settings' THEN IF length(payload->>'supportEmail')>255 OR length(payload->>'en')>500 OR length(payload->>'ar')>500 THEN RAISE EXCEPTION 'Invalid settings'; END IF; INSERT INTO public.platform_settings(id,support_email,announcement_en,announcement_ar,updated_by) VALUES(true,coalesce(payload->>'supportEmail',''),coalesce(payload->>'en',''),coalesce(payload->>'ar',''),uid) ON CONFLICT(id) DO UPDATE SET support_email=EXCLUDED.support_email,announcement_en=EXCLUDED.announcement_en,announcement_ar=EXCLUDED.announcement_ar,updated_at=now(),updated_by=uid;
ELSE RAISE EXCEPTION 'Unknown admin action'; END IF;
RETURN jsonb_build_object('ok',true);
EXCEPTION WHEN OTHERS THEN INSERT INTO public.admin_audit_log(actor_id,action,entity_type,entity_id,outcome) VALUES(uid,action,'admin_operation',coalesce(payload->>'id',payload->>'userId','settings'),'failed'); RETURN jsonb_build_object('ok',false); END;
END $$;
REVOKE ALL ON FUNCTION public.admin_manage(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_manage(text,jsonb) TO authenticated;
DO $rewards$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.recycling_action(text,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'IF v.used_at IS NOT NULL OR v.expires_at<=now()', 'IF v.admin_review<>''approved'' OR v.used_at IS NOT NULL OR v.expires_at<=now()'); EXECUTE definition; END $rewards$;